import 'dart:io';

class AppConfig {
  /// Web Client ID generated by Firebase / Google Cloud Console for backend token audience validation
  static const String webClientId =
      '533947683458-3tn9eggu70uob8pv4g1kj7kj4j3rjilk.apps.googleusercontent.com';

  /// iOS Client ID for native iOS Google Sign-In
  static const String iosClientId =
      '533947683458-f16dl0kle0is987gqoqum4255pqerhta.apps.googleusercontent.com';

  /// Returns platform-specific Google Sign-In client ID if needed by platform
  static String? get googleClientId {
    if (Platform.isIOS) {
      return iosClientId;
    }
    return null;
  }

  /// Returns the serverClientId used on Android & iOS to request a Web-audience ID Token for backend verification
  static String get serverClientId => webClientId;
}
